        if (a < b) {
            res.append("Obtuse-angled Triangle");
            return res.toString();
        } else if (a == b) {
            res.append("Acute-angled Triangle");
            return res.toString();
        } else if (a == c) {
            res.append("Right-angled Triangle");
            return res.toString();
        }
        res.append("Obtuse-angled Triangle");
        return res.toString();
    }
}

